use std::cmp::Reverse;
use std::collections::BinaryHeap;

// adj[u] = Vec of (v, w)
fn dijkstra(n: usize, adj: &Vec<Vec<(usize, i64)>>, src: usize) -> Vec<i64> {
    let inf = i64::MAX / 4;
    let mut dist = vec![inf; n];
    dist[src] = 0;
    let mut heap = BinaryHeap::new(); // max-heap of Reverse((dist, node)) => min-heap
    heap.push(Reverse((0i64, src)));
    while let Some(Reverse((d, u))) = heap.pop() {
        if d != dist[u] { continue; }
        for &(v, w) in &adj[u] {
            let nd = d + w;
            if nd < dist[v] { dist[v] = nd; heap.push(Reverse((nd, v))); }
        }
    }
    dist
}

#[derive(Clone)]
struct DSU { p: Vec<usize>, r: Vec<i32> }
impl DSU {
    fn new(n: usize) -> Self { Self { p: (0..n).collect(), r: vec![0; n] } }
    fn find(&mut self, x: usize) -> usize { if self.p[x]==x { x } else { let px = self.find(self.p[x]); self.p[x]=px; px } }
    fn unite(&mut self, a: usize, b: usize) -> bool { let mut a=self.find(a); let mut b=self.find(b); if a==b { return false } if self.r[a]<self.r[b] { std::mem::swap(&mut a,&mut b) } self.p[b]=a; if self.r[a]==self.r[b] { self.r[a]+=1 } true }
}

// edges: (u,v,w)
fn kruskal_mst(n: usize, mut edges: Vec<(usize,usize,i64)>) -> i64 {
    edges.sort_by_key(|e| e.2);
    let mut dsu = DSU::new(n);
    let mut total: i64 = 0;
    let mut cnt = 0;
    for (u,v,w) in edges { if dsu.unite(u,v) { total += w; cnt += 1; if cnt==n-1 { break } } }
    if cnt==n-1 { total } else { -1 }
}

// edges: (u,v,w)
fn bellman_ford(n: usize, edges: &Vec<(usize,usize,i64)>, src: usize) -> (Vec<i64>, bool) {
    let inf = i64::MAX/4;
    let mut dist = vec![inf; n]; dist[src]=0;
    for _ in 1..=n-1 {
        let mut updated = false;
        for &(u,v,w) in edges { if dist[u]!=inf && dist[u]+w < dist[v] { dist[v]=dist[u]+w; updated=true; } }
        if !updated { break }
    }
    for &(u,v,w) in edges { if dist[u]!=inf && dist[u]+w < dist[v] { return (dist, true) } }
    (dist, false)
}

fn topo_sort_kahn(n: usize, adj: &Vec<Vec<usize>>) -> Vec<usize> {
    let mut indeg = vec![0usize; n];
    for u in 0..n { for &v in &adj[u] { indeg[v]+=1; } }
    let mut q: Vec<usize> = Vec::new();
    for i in 0..n { if indeg[i]==0 { q.push(i); } }
    let mut order: Vec<usize> = Vec::with_capacity(n);
    let mut h = 0usize;
    while h < q.len() {
        let u = q[h]; h+=1; order.push(u);
        for &v in &adj[u] { indeg[v]-=1; if indeg[v]==0 { q.push(v); } }
    }
    order
}

fn kmp_search(text: &str, pat: &str) -> Vec<usize> {
    let n = text.len(); let m = pat.len(); if m==0 { return vec![] }
    let tb = text.as_bytes(); let pb = pat.as_bytes();
    let mut lps = vec![0usize; m];
    let (mut i, mut l) = (1usize, 0usize);
    while i < m { if pb[i]==pb[l] { l+=1; lps[i]=l; i+=1; } else if l>0 { l=lps[l-1]; } else { lps[i]=0; i+=1; } }
    let mut res = Vec::new();
    let (mut x, mut y) = (0usize, 0usize);
    while x < n { if tb[x]==pb[y] { x+=1; y+=1; if y==m { res.push(x-m); y=lps[y-1]; } } else if y>0 { y=lps[y-1]; } else { x+=1; } }
    res
}

fn rabin_karp(text: &str, pat: &str) -> Vec<usize> {
    let n = text.len(); let m = pat.len(); if m==0 || m>n { return vec![] }
    const B: u64 = 131; const MOD: u64 = 1_000_000_007;
    let tb = text.as_bytes(); let pb = pat.as_bytes();
    let mut powb = 1u64; for _ in 0..m-1 { powb = (powb * B) % MOD }
    let (mut hpat, mut hwin) = (0u64, 0u64);
    for i in 0..m { hpat = (hpat*B + pb[i] as u64) % MOD; hwin = (hwin*B + tb[i] as u64) % MOD }
    let mut out = Vec::new();
    for i in 0..=n-m {
        if hpat==hwin && &text[i..i+m] == pat { out.push(i) }
        if i < n-m {
            hwin = ( (hwin + MOD - (tb[i] as u64)*powb%MOD) % MOD );
            hwin = (hwin*B + tb[i+m] as u64) % MOD;
        }
    }
    out
}

fn sieve_is_prime(n: usize) -> Vec<bool> {
    let mut is = vec![true; n+1];
    if n>=0 { is[0]=false }
    if n>=1 { is[1]=false }
    let mut p = 2usize;
    while p*p <= n {
        if is[p] { let mut x = p*p; while x <= n { is[x] = false; x += p } }
        p+=1;
    }
    is
}

fn edit_distance(a: &str, b: &str) -> usize {
    let (m, n) = (a.len(), b.len());
    let ab = a.as_bytes(); let bb = b.as_bytes();
    let mut prev: Vec<usize> = (0..=n).collect();
    let mut cur = vec![0usize; n+1];
    for i in 1..=m {
        cur[0] = i; let ai = ab[i-1];
        for j in 1..=n {
            let cost = if ai==bb[j-1] { 0 } else { 1 };
            let del = prev[j] + 1; let ins = cur[j-1] + 1; let rep = prev[j-1] + cost;
            cur[j] = del.min(ins).min(rep);
        }
        std::mem::swap(&mut prev, &mut cur);
    }
    prev[n]
}

fn lis_length(a: &[i64]) -> usize {
    let mut tails: Vec<i64> = Vec::new();
    for &x in a {
        let i = lower_bound(&tails, x);
        if i==tails.len() { tails.push(x); } else { tails[i]=x; }
    }
    tails.len()
}
fn lower_bound(a: &Vec<i64>, x: i64) -> usize {
    let (mut l, mut r) = (0usize, a.len());
    while l<r { let m=(l+r)/2; if a[m]>=x { r=m } else { l=m+1 } }
    l
}

fn quickselect(a: &mut [i64], mut k: usize) -> i64 { // k: 1-based
    let (mut l, mut r) = (0usize, a.len()-1); k-=1;
    while l<=r {
        let pivot = a[r]; let mut i = l;
        for j in l..r { if a[j] <= pivot { a.swap(i,j); i+=1 } }
        a.swap(i,r);
        if i==k { return a[i] } else if i>k { if i==0 { break } r = i-1; } else { l = i+1; }
    }
    panic!("k out of range");
}

